"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";
import type { GroupAnalysis } from "@/domain/group";
import type { Chapter } from "@/domain/types";
import type { GroupAiPayload } from "@/llm/group";
import { AiProgressSignal, TELESCOPE_AI_PROGRESS_EVENT, type AiProgressState } from "./Report";
import type { LocalGroupStickerVisuals, LocalStickerVisual } from "./sticker-assets";
import { FittedQuote } from "./FittedQuote";

const formatDate = (ts: number) => new Date(ts * 1000).toLocaleDateString("en", { month: "short", year: "numeric" });
type GroupSlide = { id: string; label: string; tone: "light" | "night"; content: ReactNode };
export interface LocalGroupMessage { id: number; ts: number; participantId: string; body: string }
export interface LocalGroupExtremeEvidence { longestMessage?: LocalGroupMessage; longestRun?: LocalGroupMessage[] }

function GroupScreen({ slide, active, index, total, direction }: { slide: GroupSlide; active: boolean; index: number; total: number; direction: 1 | -1 }) {
  const night = slide.tone === "night";
  return <section aria-hidden={!active} className={`wrapped-screen wrapped-variant-${index % 4} absolute inset-0 flex h-dvh w-full overflow-hidden px-5 pb-20 pt-16 sm:px-10 xl:px-20 ${night ? "report-night-slide starfield bg-night" : "bg-surface"} ${active ? `wrapped-active wrapped-${direction === 1 ? "forward" : "reverse"} z-10` : "wrapped-inactive pointer-events-none z-0"}`}>
    <div aria-hidden="true" className="wrapped-atmosphere"><span className="wrapped-orbit" /><span className="wrapped-orbit wrapped-orbit-two" /><span className="wrapped-sweep" /></div>
    <div className="wrapped-content relative m-auto w-full max-w-[1180px]">{slide.content}</div>
    <div className={`absolute bottom-6 left-5 flex items-baseline gap-3 font-mono uppercase sm:left-10 xl:left-20 ${night ? "text-white" : "text-ink"}`}><span className="text-[9px] tracking-[.14em] opacity-30">{String(index + 1).padStart(2, "0")} / {String(total).padStart(2, "0")}</span><span className="text-[clamp(.78rem,1.15vw,1rem)] tracking-[.12em] opacity-60 max-[640px]:hidden">{slide.label}</span></div>
  </section>;
}

const Eyebrow = ({ children, light = false }: { children: ReactNode; light?: boolean }) => <p className={`font-mono text-[clamp(.95rem,1.5vw,1.3rem)] font-semibold uppercase tracking-[.16em] ${light ? "text-accent" : "text-accent-lit"}`}>{children}</p>;

const GroupScrollArea = ({ children }: { children: ReactNode }) => <div data-report-navigation-lock className="group-report-scroll mt-8 min-h-0 flex-1 overflow-y-auto overscroll-contain pr-2">{children}</div>;

const groupColors = ["var(--color-accent-lit)", "var(--color-side-a)", "var(--color-safe)", "var(--color-warn)"];
const eraColors = ["var(--color-accent)", "var(--color-safe)", "var(--color-warn)", "var(--color-accent-lit)", "var(--color-safe-deep)"];
const hourLabel = (hour: number) => hour === 0 ? "12 am" : hour < 12 ? `${hour} am` : hour === 12 ? "12 pm" : `${hour - 12} pm`;
const duration = (seconds: number) => seconds >= 86400 ? `${Math.round(seconds / 86400).toLocaleString()} days` : seconds >= 3600 ? `${Math.round(seconds / 3600)} hours` : `${Math.round(seconds / 60)} min`;

function WhoStartsGroup({ analysis }: { analysis: GroupAnalysis }) {
  const leader = analysis.starters[0];
  return <div><Eyebrow light>Who starts it?</Eyebrow><h2 className="mt-4 max-w-[980px] font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-ink">{leader ? <><span className="text-accent">{leader.name}</span> brought the room back {Math.round(leader.share * 100)}% of the time.</> : "This group never really stopped."}</h2><p className="mt-5 max-w-[720px] text-sm leading-relaxed text-ink/52">{analysis.restartCount ? `${analysis.restartCount.toLocaleString()} conversations restarted after more than two hours of silence. The first message after the gap gets the credit.` : "A restart needs more than two hours of silence. This chat never stayed quiet that long."}</p>{analysis.restartCount > 0 && <div className="mt-9 max-w-[980px] border-t border-ink/14">{analysis.starters.slice(0, 6).map((person, index) => <div key={person.id} className="grid grid-cols-[minmax(90px,180px)_1fr_auto] items-center gap-4 border-b border-ink/12 py-3"><span className="truncate font-display text-xl text-ink">{person.name}</span><span className="h-3 overflow-hidden rounded-full bg-ink/8"><span className="block h-full rounded-full" style={{ width: `${person.share * 100}%`, background: groupColors[index % groupColors.length] }} /></span><span className="font-mono text-[9px] uppercase tracking-[.1em] text-ink/42">{person.count} · {Math.round(person.share * 100)}%</span></div>)}</div>}</div>;
}

function GroupMonthly({ analysis }: { analysis: GroupAnalysis }) {
  const peak = Math.max(1, ...analysis.monthly.map((month) => month.total));
  return <div><Eyebrow light>Volume over time</Eyebrow><h2 className="mt-4 font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-ink">Messages per month.</h2><p className="mt-5 max-w-[760px] text-sm leading-relaxed text-ink/52">Busiest month held {peak.toLocaleString()} messages. Empty months stay visible, so quiet stretches take up their real amount of time.</p><div className="mt-9 flex h-[clamp(150px,34vh,340px)] items-end gap-[3px]">{analysis.monthly.map((month) => <span key={month.month} title={`${month.month} · ${month.total.toLocaleString()} messages`} tabIndex={0} className="group relative h-full min-w-0 flex-1 outline-none"><span className="absolute inset-x-0 bottom-0 block rounded-t-sm bg-accent transition group-hover:bg-accent-deep group-focus-visible:bg-accent-deep" style={{ height: `${Math.max(month.total ? 1.5 : 0, month.total / peak * 100)}%` }} /></span>)}</div><div className="mt-3 flex gap-[3px] border-t border-ink/12 pt-3 font-mono text-[9px] text-ink/42">{analysis.monthly.map((month, index) => <span key={month.month} className="relative h-4 min-w-0 flex-1">{(index === 0 || month.month.endsWith("-01")) && <span className={`absolute top-0 ${index > analysis.monthly.length - 6 ? "right-0" : "left-0"}`}>{month.month.slice(0, 4)}</span>}</span>)}</div></div>;
}

function GroupClock({ analysis }: { analysis: GroupAnalysis }) {
  const peak = Math.max(1, ...analysis.hourly);
  const peakHour = analysis.hourly.indexOf(Math.max(...analysis.hourly));
  const shownIds = new Set(analysis.hourlyByParticipant.map((person) => person.id));
  return <div><Eyebrow>The clock</Eyebrow><h2 className="mt-4 font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-white">When the group talks.</h2><p className="mt-5 max-w-[760px] text-sm leading-relaxed text-white/52">Busiest hour is {hourLabel(peakHour)}. Each column keeps the group&rsquo;s busiest voices stacked inside the total.</p><div className="mt-9 flex flex-wrap gap-x-5 gap-y-2 font-mono text-[8px] uppercase tracking-[.1em] text-white/44">{analysis.hourlyByParticipant.map((person, index) => <span key={person.id} className="flex items-center gap-2"><i className="h-2 w-2 rounded-full" style={{ background: groupColors[index] }} />{person.name}</span>)}{analysis.participants.some((person) => !shownIds.has(person.id)) && <span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full bg-white/22" />Everyone else</span>}</div><div className="mt-5 flex h-[clamp(140px,30vh,310px)] items-end gap-[3px]">{analysis.hourly.map((total, hour) => { const known = analysis.hourlyByParticipant.reduce((sum, person) => sum + person.counts[hour], 0); return <span key={hour} title={`${hourLabel(hour)} · ${total.toLocaleString()} messages`} tabIndex={0} className="flex h-full min-w-0 flex-1 flex-col justify-end gap-px outline-none">{total > known && <span className="block bg-white/22" style={{ height: `${(total - known) / peak * 100}%` }} />}{[...analysis.hourlyByParticipant].reverse().map((person, reverseIndex) => { const index = analysis.hourlyByParticipant.length - reverseIndex - 1; return <span key={person.id} className="block first:rounded-t-sm" style={{ height: `${person.counts[hour] / peak * 100}%`, background: groupColors[index] }} />; })}</span>; })}</div><div className="mt-3 flex gap-[3px] border-t border-white/14 pt-3 font-mono text-[9px] text-white/40">{analysis.hourly.map((_, hour) => <span key={hour} className="relative h-4 min-w-0 flex-1">{hour % 3 === 0 && <span className="absolute left-0 top-0">{String(hour).padStart(2, "0")}</span>}</span>)}</div></div>;
}

function GroupSpeech({ analysis }: { analysis: GroupAnalysis }) {
  const rows = [{ value: analysis.speech.averageChars.toFixed(0), label: "characters per message" }, { value: `${(analysis.speech.mediaShare * 100).toFixed(1)}%`, label: "of messages include media" }, { value: `${(analysis.speech.consecutiveShare * 100).toFixed(1)}%`, label: "follow another message by the same person" }];
  return <div><Eyebrow>How you speak</Eyebrow><h2 className="mt-4 max-w-[900px] font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-white">The group has its own cadence.</h2><div className="mt-9 grid gap-7 lg:grid-cols-[1fr_1.15fr]"><dl className="grid grid-cols-3 border-y border-white/14">{rows.map((row, index) => <div key={row.label} className={`${index ? "border-l border-white/14 pl-4" : ""} py-5`}><dd className="font-display text-[clamp(1.9rem,4vw,4rem)] leading-none text-white">{row.value}</dd><dt className="mt-2 text-xs leading-tight text-white/42">{row.label}</dt></div>)}</dl><div className="border-t border-white/14">{analysis.speech.topAverageChars.map((person, index) => <div key={person.id} className="grid grid-cols-[24px_1fr_auto] gap-3 border-b border-white/12 py-3"><span className="font-mono text-[9px] text-accent-lit">0{index + 1}</span><span className="truncate text-sm text-white/70">{person.name}</span><span className="font-mono text-[9px] text-white/38">{person.value.toFixed(0)} chars / message</span></div>)}</div></div></div>;
}

function GroupEmoji({ analysis }: { analysis: GroupAnalysis }) {
  const people = analysis.emoji ?? [];
  return <div className="flex max-h-[calc(100dvh-9rem)] min-h-0 flex-col"><div className="shrink-0"><Eyebrow>Emoji</Eyebrow><h2 className="mt-4 max-w-[980px] font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-white">Every voice has a <span className="italic text-accent-lit">reaction vocabulary.</span></h2><p className="mt-5 text-sm text-white/52">The emoji each person typed into their own messages.</p></div><GroupScrollArea><ol className="grid border-t border-white/14 sm:grid-cols-2">{people.map((person, index) => <li key={person.id} className={`border-b border-white/12 py-5 sm:px-6 ${index % 2 ? "sm:border-l" : "sm:pl-0"}`}><div className="flex items-center justify-between gap-4"><h3 className="truncate font-display text-2xl" style={{ color: groupColors[index % groupColors.length] }}>{person.name}</h3><span className="font-mono text-[8px] uppercase tracking-[.1em] text-white/30">{person.total.toLocaleString()} emoji</span></div><p className="mt-4 text-[clamp(1.8rem,4vw,3.8rem)] leading-none">{person.top.map((item) => item.emoji).join(" ")}</p><p className="mt-3 font-mono text-[8px] text-white/30">{person.top.map((item) => `${item.emoji} ${item.count.toLocaleString()}×`).join(" · ")}</p></li>)}</ol></GroupScrollArea></div>;
}

function GroupStickerSpecimen({ sticker }: { sticker: LocalStickerVisual }) {
  return <div className="min-w-0"><div className="grid aspect-square place-items-center overflow-hidden rounded-[14px] bg-white/[.055]">{sticker.video ? <video src={sticker.src} autoPlay loop muted playsInline className="h-full w-full object-contain" /> : <img src={sticker.src} alt={sticker.emoji ? `${sticker.emoji} sticker` : "Telegram sticker"} className="h-full w-full object-contain" />}</div><p className="mt-1 text-center font-mono text-[7px] text-white/30">{sticker.count}×</p></div>;
}

function GroupStickers({ analysis, visuals }: { analysis: GroupAnalysis; visuals?: LocalGroupStickerVisuals }) {
  const people = analysis.stickers ?? [];
  return <div className="flex max-h-[calc(100dvh-9rem)] min-h-0 flex-col"><div className="shrink-0"><Eyebrow>Stickers</Eyebrow><h2 className="mt-4 max-w-[980px] font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-white">The images that did the talking.</h2><p className="mt-5 text-sm text-white/52">Top sent stickers by person. Artwork appears when the complete Telegram export folder is available on this device.</p></div><GroupScrollArea><ol className="grid border-t border-white/14 sm:grid-cols-2">{people.map((person, index) => { const art = visuals?.[person.id]; return <li key={person.id} className={`border-b border-white/12 py-5 sm:px-6 ${index % 2 ? "sm:border-l" : "sm:pl-0"}`}><div className="flex items-center justify-between gap-4"><h3 className="truncate font-display text-2xl" style={{ color: groupColors[index % groupColors.length] }}>{person.name}</h3><span className="font-mono text-[8px] uppercase tracking-[.1em] text-white/30">{person.total.toLocaleString()} stickers</span></div>{art?.length ? <div className="mt-4 grid max-w-[360px] grid-cols-5 gap-2">{art.map((sticker) => <GroupStickerSpecimen key={sticker.path} sticker={sticker} />)}</div> : <p className="mt-4 text-[clamp(1.7rem,3.5vw,3rem)] leading-none">{person.top.map((item) => item.emoji).join(" ")}</p>}</li>; })}</ol></GroupScrollArea></div>;
}

function GroupDoubleTexter({ analysis, names, evidence }: { analysis: GroupAnalysis; names: Map<string, string>; evidence?: LocalGroupMessage[] }) {
  const [open, setOpen] = useState(false);
  const metric = analysis.doubleTexting;
  const longest = metric?.longest;
  const winner = longest ? names.get(longest.participantId) ?? "Unknown" : null;
  useEffect(() => { if (!open) return; const close = (event: KeyboardEvent) => { if (event.key === "Escape") setOpen(false); }; window.addEventListener("keydown", close); return () => window.removeEventListener("keydown", close); }, [open]);
  if (!metric) return null;
  return <div><Eyebrow>Double Texter Award</Eyebrow><h2 className="mt-4 max-w-[980px] font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-white">{longest ? <><span className="text-accent-lit">{winner}</span> reached {longest.doubleTexts.toLocaleString()} follow-ups without a reply.</> : "Nobody double texted."}</h2><p className="mt-5 max-w-[760px] text-sm leading-relaxed text-white/52">A double text is another unanswered message sent at least two minutes after the previous one. There is no maximum gap.</p>{longest && <div className="mt-8 grid max-w-[1040px] items-end gap-7 border-y border-white/14 py-6 md:grid-cols-[.8fr_1.2fr]"><div><p className="font-display text-[clamp(3.5rem,8vw,8rem)] leading-[.72] text-accent-lit">{longest.doubleTexts.toLocaleString()}</p><p className="mt-4 font-mono text-[9px] uppercase tracking-[.14em] text-white/38">qualifying follow-ups · {longest.messages.toLocaleString()} messages in the run</p><button type="button" onClick={() => setOpen(true)} className="mt-5 rounded-full border border-white/20 px-5 py-2.5 text-sm text-white/72 transition hover:border-accent-lit hover:text-white">View the actual streak ↗</button></div><ol className="border-t border-white/14">{metric.frequency.filter((person) => person.count).slice(0, 6).map((person, index) => <li key={person.id} className="grid grid-cols-[28px_1fr_auto] border-b border-white/12 py-2.5"><span className="font-mono text-[8px] text-accent-lit">0{index + 1}</span><span className="truncate text-sm text-white/68">{person.name}</span><span className="font-mono text-[8px] text-white/34">{person.count.toLocaleString()}</span></li>)}</ol></div>}{open && longest && <div className="fixed inset-0 z-[100] grid place-items-center bg-night/84 px-4 py-6 backdrop-blur-md" role="dialog" aria-modal="true" aria-labelledby="group-double-text-title" onClick={(event) => { event.stopPropagation(); if (event.target === event.currentTarget) setOpen(false); }}><section className="rise flex max-h-[86dvh] w-full max-w-[720px] flex-col overflow-hidden rounded-[26px] border border-white/14 bg-night text-white shadow-2xl" onClick={(event) => event.stopPropagation()}><header className="flex items-start justify-between gap-5 border-b border-white/12 px-6 py-5"><div><p className="font-mono text-[9px] uppercase tracking-[.18em] text-accent-lit">The receipts</p><h3 id="group-double-text-title" className="mt-2 font-display text-[clamp(2rem,5vw,3.8rem)] leading-none">{winner}&rsquo;s longest streak.</h3></div><button type="button" onClick={() => setOpen(false)} aria-label="Close streak" className="grid h-10 w-10 place-items-center rounded-full border border-white/16 text-xl text-white/45">×</button></header><div className="overflow-y-auto px-5 py-6">{evidence?.length ? <ol className="space-y-3">{evidence.map((message) => <li key={message.id}><p className="mb-1 font-mono text-[8px] uppercase tracking-[.12em] text-accent-lit">{names.get(message.participantId) ?? "Unknown"} · {new Date(message.ts * 1000).toLocaleString()}</p><p className="rounded-[18px] border border-white/10 bg-white/[.06] px-4 py-3 text-sm leading-relaxed text-white/78">{message.body}</p></li>)}</ol> : <p className="py-12 text-center text-sm text-white/45">The messages stayed on the original device.</p>}</div></section></div>}</div>;
}

function GroupLanguage({ analysis }: { analysis: GroupAnalysis }) {
  const people = analysis.language.distinctive.filter((person) => person.words.length);
  return <div className="flex max-h-[calc(100dvh-9rem)] min-h-0 flex-col"><div className="shrink-0"><Eyebrow>Your language</Eyebrow><h2 className="mt-4 max-w-[980px] font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-white">The words that sound most like <span className="italic text-accent-lit">each person.</span></h2><p className="mt-5 max-w-[720px] text-sm leading-relaxed text-white/52">Not the room&rsquo;s most common words—the language each person uses more distinctively than everyone else.</p></div>{people.length ? <GroupScrollArea><ol className="grid border-t border-white/14 sm:grid-cols-2">{people.map((person, index) => <li key={person.id} className={`border-b border-white/12 py-5 sm:px-6 ${index % 2 ? "sm:border-l" : "sm:pl-0"}`}><div className="flex items-center gap-3"><span className="font-mono text-[8px] text-white/28">{String(index + 1).padStart(2, "0")}</span><h3 className="truncate font-display text-2xl" style={{ color: groupColors[index % groupColors.length] }}>{person.name}</h3></div><div className="mt-4 flex flex-wrap gap-x-5 gap-y-3">{person.words.map((word) => <span key={word.word} className="inline-flex items-baseline gap-2"><span className="font-display text-[clamp(1.45rem,2.8vw,2.8rem)] leading-none text-white">“{word.word}”</span><span className="font-mono text-[8px] text-white/30">{word.count.toLocaleString()}×</span></span>)}</div></li>)}</ol></GroupScrollArea> : <p className="mt-9 border-y border-white/14 py-8 text-sm text-white/42">No person-specific language cleared the minimum repeat threshold in this export.</p>}</div>;
}

function StrongestPair({ analysis }: { analysis: GroupAnalysis }) {
  const pair = analysis.strongestPair;
  if (!pair) return null;
  return <div className="text-center"><Eyebrow>The strongest axis</Eyebrow><h2 className="mx-auto mt-5 max-w-[1040px] font-display text-[clamp(3.2rem,8vw,8rem)] leading-[.8] tracking-[-.04em] text-white"><span className="text-side-a">{pair.firstName}</span> <span className="text-white/22">&amp;</span> <span className="italic text-side-b">{pair.secondName}</span></h2><div className="mx-auto mt-9 flex max-w-[760px] items-center gap-5"><span className="h-px flex-1 bg-gradient-to-r from-transparent to-side-a" /><span className="font-display text-[clamp(2.5rem,6vw,5.5rem)] text-accent-lit">{pair.replies.toLocaleString()}</span><span className="h-px flex-1 bg-gradient-to-r from-side-b to-transparent" /></div><p className="mt-3 font-mono text-[9px] uppercase tracking-[.16em] text-white/38">direct replies between them · both directions combined</p></div>;
}

function ReactionMagnet({ analysis }: { analysis: GroupAnalysis }) {
  const leaders = analysis.reactionLeaders;
  const peak = leaders[0]?.reactions ?? 1;
  const topReactions = leaders[0]?.topReactions ?? [];
  return <div><Eyebrow>Reaction magnet</Eyebrow><h2 className="mt-4 max-w-[980px] font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-white"><span className="text-accent-lit">{leaders[0]?.name}</span> got the room to react.</h2><p className="mt-5 text-sm text-white/52">Reactions attached to each person&rsquo;s messages in the Telegram export.</p>{topReactions.length > 0 && <div className="mt-7 flex flex-wrap items-end gap-x-6 gap-y-3 border-y border-white/12 py-4" aria-label={`${leaders[0]?.name}'s top reactions`}>{topReactions.map((reaction, index) => <div key={reaction.emoji} className="flex items-baseline gap-2"><span className={index === 0 ? "text-4xl" : "text-2xl"} aria-hidden="true">{reaction.emoji}</span><span className="font-mono text-[9px] text-white/42">{reaction.count.toLocaleString()}</span></div>)}</div>}<ol className={`${topReactions.length ? "mt-5" : "mt-9"} max-w-[980px] border-t border-white/14`}>{leaders.slice(0, 7).map((person, index) => <li key={person.id} className="grid grid-cols-[28px_minmax(90px,200px)_1fr_auto] items-center gap-3 border-b border-white/12 py-3 sm:gap-5"><span className="font-mono text-[9px] text-accent-lit">0{index + 1}</span><span className="truncate font-display text-xl sm:text-2xl">{person.name}</span><span className="h-2 overflow-hidden rounded-full bg-white/8"><span className="block h-full rounded-full bg-accent-lit" style={{ width: `${person.reactions / peak * 100}%` }} /></span><span className="font-mono text-[9px] uppercase tracking-[.1em] text-white/38">{person.reactions.toLocaleString()} reactions</span></li>)}</ol></div>;
}

function ChangingRoom({ analysis }: { analysis: GroupAnalysis }) {
  const leaders = analysis.monthlyLeaders.filter((month) => month.participantId);
  const leaderIds = [...new Set(leaders.map((month) => month.participantId!))];
  const colors = new Map(leaderIds.map((id, index) => [id, groupColors[index % groupColors.length]]));
  const mostLed = [...leaderIds].map((id) => ({ id, months: leaders.filter((month) => month.participantId === id).length })).sort((a, b) => b.months - a.months)[0];
  const names = new Map(analysis.participants.map((person) => [person.id, person.name]));
  return <div><Eyebrow light>The changing room</Eyebrow><h2 className="mt-4 max-w-[980px] font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-ink">{mostLed ? <><span className="text-accent">{names.get(mostLed.id)}</span> led the most months.</> : "No month had a voice to lead it."}</h2><p className="mt-5 max-w-[760px] text-sm leading-relaxed text-ink/52">Each stripe belongs to the person who sent the most messages that month. Grey marks a month when the group was silent.</p><div className="mt-8 flex flex-wrap gap-x-5 gap-y-2 font-mono text-[8px] uppercase tracking-[.1em] text-ink/46">{leaderIds.slice(0, 8).map((id) => <span key={id} className="flex items-center gap-2"><i className="h-2 w-2 rounded-full" style={{ background: colors.get(id) }} />{names.get(id)}</span>)}</div><div className="mt-7 flex h-[clamp(110px,22vh,210px)] items-stretch gap-[3px] border-b border-ink/14">{analysis.monthlyLeaders.map((month) => <span key={month.month} title={`${month.month} · ${month.name ?? "No messages"}${month.name ? ` led with ${month.messages.toLocaleString()}` : ""}`} className="min-w-0 flex-1 rounded-t-sm" style={{ background: month.participantId ? colors.get(month.participantId) : "rgba(23,33,43,.1)", opacity: month.participantId ? .35 + month.share * .65 : 1 }} />)}</div><div className="mt-3 flex justify-between font-mono text-[9px] text-ink/40"><span>{analysis.monthlyLeaders[0]?.month}</span><span>{analysis.monthlyLeaders.at(-1)?.month}</span></div></div>;
}

function GroupExtremes({ analysis, names, evidence }: { analysis: GroupAnalysis; names: Map<string, string>; evidence?: LocalGroupExtremeEvidence }) {
  const [open, setOpen] = useState<"message" | "run" | null>(null);
  useEffect(() => {
    if (!open) return;
    const close = (event: KeyboardEvent) => { if (event.key === "Escape") setOpen(null); };
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, [open]);
  const rows: Array<{ value: string; label: string; reveal?: "message" | "run" }> = [
    { value: duration(analysis.extremes.longestSilenceSec), label: "longest silence" },
    { value: analysis.extremes.busiestDay?.messages.toLocaleString() ?? "—", label: "messages on the busiest day" },
    { value: `${analysis.extremes.longestMessage?.chars.toLocaleString() ?? 0} chars`, label: `longest message · ${names.get(analysis.extremes.longestMessage?.participantId ?? "") ?? "—"}`, reveal: "message" },
    { value: `${analysis.extremes.longestRun?.messages.toLocaleString() ?? 0} messages`, label: `longest unbroken run · ${names.get(analysis.extremes.longestRun?.participantId ?? "") ?? "—"}`, reveal: "run" },
  ];
  const shown = open === "message" ? (evidence?.longestMessage ? [evidence.longestMessage] : undefined) : evidence?.longestRun;
  return <div><Eyebrow light>The extremes</Eyebrow><h2 className="mt-4 max-w-[940px] font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-ink">The biggest, longest and quietest.</h2><p className="mt-5 text-sm text-ink/52">Single moments rather than tendencies—the records that beat every other day, message and silence.</p><dl className="mt-8 grid grid-cols-2 gap-x-8 border-y border-ink/16 lg:grid-cols-4">{rows.map((row, index) => <div key={row.label} className={`py-5 ${index % 2 ? "border-l border-ink/16 pl-5" : ""} lg:border-l lg:border-ink/16 lg:pl-5`}><dd className="font-display text-[clamp(1.8rem,3.6vw,3.8rem)] leading-none text-ink">{row.reveal ? <button type="button" onClick={() => setOpen(row.reveal!)} className="text-left underline decoration-accent/35 decoration-2 underline-offset-[7px] transition hover:text-accent">{row.value}</button> : row.value}</dd><dt className="mt-2 text-xs leading-tight text-ink/48">{row.label}{row.reveal && <span className="mt-1 block font-mono text-[8px] uppercase tracking-[.1em] text-accent">click to reveal ↗</span>}</dt></div>)}</dl>{open && <div className="fixed inset-0 z-[90] grid place-items-center bg-night/84 px-4 py-6 backdrop-blur-md" role="dialog" aria-modal="true" aria-labelledby="group-extreme-receipt-title" onClick={(event) => { event.stopPropagation(); if (event.target === event.currentTarget) setOpen(null); }}><section className="rise flex max-h-[86dvh] w-full max-w-[760px] flex-col overflow-hidden rounded-[26px] border border-white/14 bg-night text-white shadow-2xl" onClick={(event) => event.stopPropagation()}><header className="flex items-start justify-between gap-5 border-b border-white/12 px-6 py-5 sm:px-8 sm:py-6"><div><p className="font-mono text-[9px] uppercase tracking-[.18em] text-accent-lit">The receipts</p><h3 id="group-extreme-receipt-title" className="mt-2 font-display text-[clamp(2rem,5vw,3.8rem)] leading-none">{open === "message" ? "The longest message." : "The longest unbroken run."}</h3><p className="mt-3 text-sm text-white/45">{open === "message" ? `${names.get(analysis.extremes.longestMessage?.participantId ?? "")} wrote ${analysis.extremes.longestMessage?.chars.toLocaleString()} characters.` : `${names.get(analysis.extremes.longestRun?.participantId ?? "")} sent ${analysis.extremes.longestRun?.messages.toLocaleString()} messages before anyone else spoke.`}</p></div><button type="button" onClick={() => setOpen(null)} aria-label="Close receipt" className="grid h-10 w-10 shrink-0 place-items-center rounded-full border border-white/16 text-xl text-white/45 transition hover:border-white/40 hover:text-white">×</button></header><div className="overflow-y-auto px-5 py-6 sm:px-8">{shown?.length ? <ol className="space-y-3">{shown.map((message) => <li key={message.id}><p className="mb-1 px-1 font-mono text-[8px] uppercase tracking-[.12em] text-accent-lit">{names.get(message.participantId) ?? "Unknown"} · {new Date(message.ts * 1000).toLocaleString()}</p><p className="whitespace-pre-wrap break-words rounded-[18px] border border-white/10 bg-white/[.06] px-4 py-3 text-sm leading-relaxed text-white/78">{message.body}</p></li>)}</ol> : <div className="py-12 text-center"><p className="font-display text-3xl">The text stayed on the original device.</p><p className="mx-auto mt-4 max-w-[48ch] text-sm leading-relaxed text-white/48">Only the record&rsquo;s message IDs and measurements were saved. Open this report in the browser where it was generated to reveal the content.</p></div>}</div><footer className="border-t border-white/12 px-6 py-4 font-mono text-[8px] uppercase tracking-[.13em] text-white/28 sm:px-8">Browser-local evidence · never stored with the report</footer></section></div>}</div>;
}

function GroupTopics({ ai }: { ai: GroupAiPayload }) {
  const topics = ai.topics ?? ai.themes ?? [];
  return <div><div><Eyebrow light>What you actually talk about</Eyebrow><h2 className="mt-4 max-w-[980px] font-display text-[clamp(2.8rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-ink">The subjects that kept coming back.</h2><p className="mt-5 max-w-[760px] text-sm leading-relaxed text-ink/52">Recurring themes from representative windows across the full timeline—not a keyword count from one loud week.</p></div><ol className="mt-8 border-t border-ink/16">{topics.slice(0, 4).map((topic, index) => <li key={topic.id} className="grid grid-cols-[34px_1fr] gap-3 border-b border-ink/16 py-3 sm:grid-cols-[44px_260px_1fr]"><span className="font-mono text-[9px] text-ink/35">0{index + 1}</span><h3 className="font-display text-[clamp(1.25rem,2.3vw,2rem)] leading-none text-ink">{topic.label}</h3><p className="hidden text-sm leading-relaxed text-ink/55 sm:block">{topic.summary}</p></li>)}</ol></div>;
}

function GroupRoles({ ai, names, evidence }: { ai: GroupAiPayload; names: Map<string, string>; evidence?: LocalGroupMessage[] }) {
  return <div className="flex max-h-[calc(100dvh-9rem)] min-h-0 flex-col"><div className="shrink-0"><Eyebrow>Group roles</Eyebrow><h2 className="mt-4 max-w-[940px] font-display text-[clamp(2.8rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-white">The part each voice plays.</h2><p className="mt-4 max-w-[700px] text-sm text-white/46">Roles describe what happens in this conversation—not who anyone is outside it.</p></div><GroupScrollArea><ol className="grid border-t border-white/14 sm:grid-cols-2">{ai.roles.map((role, index) => <li key={`${role.participantId}-${role.title}`} className={`border-b border-white/12 py-4 sm:px-5 ${index % 2 ? "sm:border-l sm:border-white/12" : "sm:pl-0"}`}><p className="font-mono text-[8px] uppercase tracking-[.14em] text-accent-lit">{names.get(role.participantId) ?? "Unknown"}</p><h3 className="mt-2 font-display text-[clamp(1.55rem,2.7vw,2.5rem)] leading-none text-white">{role.title}</h3><p className="mt-2 text-xs leading-relaxed text-white/46">{role.description}</p></li>)}</ol></GroupScrollArea></div>;
}

function WildTextGame({ item, position, total, participants, names }: { item: GroupAiPayload["wildTexts"][number]; position: number; total: number; participants: GroupAnalysis["participants"]; names: Map<string, string> }) {
  const [guess, setGuess] = useState<string | null>(null);
  const revealed = guess !== null;
  return <div className="text-center"><Eyebrow>Wild texts · {position} / {total}</Eyebrow><div className="mx-auto mt-7 max-w-[900px]"><FittedQuote text={item.body} maxSize={96} className="text-white" /></div><p className="mt-6 font-mono text-[9px] uppercase tracking-[.14em] text-white/38">Who said that?</p><div className="mx-auto mt-5 flex max-w-[900px] flex-wrap justify-center gap-2">{participants.map((person) => <button key={person.id} type="button" disabled={revealed} onClick={() => setGuess(person.id)} className={`rounded-full border px-4 py-2 text-xs transition ${revealed && person.id === item.participantId ? "border-safe-lit bg-safe-lit text-night" : revealed && person.id === guess ? "border-side-a text-side-a" : "border-white/16 text-white/60 hover:border-accent-lit hover:text-white"}`}>{person.name}</button>)}</div>{revealed && <div className="mt-7"><p className="font-display text-2xl text-accent-lit">{guess === item.participantId ? "Correct." : `It was ${names.get(item.participantId)}.`}</p><p className="mx-auto mt-2 max-w-[60ch] text-xs leading-relaxed text-white/42">{item.reason}</p><p className="mt-4 font-mono text-[8px] uppercase tracking-[.12em] text-white/28">Use the report arrow to continue</p></div>}</div>;
}

function groupEraChangeLine(chapter: Extract<Chapter, { kind: "era" }>): string | null {
  const change = chapter.change?.strongest[0];
  if (!change) return null;
  const value = (n: number) => change.metric.includes("share") || change.metric === "emoji rate" ? `${Math.round(n * 100)}%` : change.metric === "words/message" ? n.toFixed(1) : Math.round(n).toLocaleString();
  return `${change.metric}: ${value(change.before)} → ${value(change.after)}`;
}

const ERA_DATE_WORDS = /\b(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?|to|through|until|from)\b/giu;

function groupEraTitle(label: string | undefined, summary: string | undefined, position: number): string {
  const candidate = label?.trim();
  if (candidate) {
    const residue = candidate
      .replace(ERA_DATE_WORDS, "")
      .replace(/\b(?:19|20)\d{2}\b/gu, "")
      .replace(/[\d\s.,/–—\-:()]+/gu, "")
      .trim();
    if (residue) return candidate;
  }

  const contextual = summary?.trim().split(/(?<=[.!?])\s/u, 1)[0]?.replace(/[.!?]+$/u, "").trim();
  if (contextual && contextual.length <= 72) return contextual;
  return `Era ${position + 1}`;
}

function GroupEraSlide({ ai, evidence, names }: { ai: GroupAiPayload; evidence?: LocalGroupMessage[]; names: Map<string, string> }) {
  const [selected, setSelected] = useState<{ chapter: Extract<Chapter, { kind: "era" }>; index: number; position: number } | null>(null);
  const notes = ai.eras.filter((era): era is typeof era & { chapterIndex: number } => typeof era.chapterIndex === "number");
  const byIndex = new Map(notes.map((note) => [note.chapterIndex, note]));
  const candidates = (ai.eraChapters ?? []).map((chapter, index) => ({ chapter, index: index + 1 })).filter((item): item is { chapter: Extract<Chapter, { kind: "era" }>; index: number } => item.chapter.kind === "era" && !item.chapter.quiet);
  const eraMessages = candidates.reduce((sum, item) => sum + item.chapter.messageCount, 0);
  const minimumMessages = Math.max(25, Math.round(eraMessages * 0.005));
  const meaningful = candidates.filter(({ chapter }) => (chapter.weeks ?? chapter.months * 4) >= 2 && chapter.messageCount >= minimumMessages);
  const retained = new Set((meaningful.length >= Math.min(3, candidates.length) ? meaningful : [...candidates].sort((a, b) => (b.chapter.share * Math.max(2, b.chapter.weeks ?? 1)) - (a.chapter.share * Math.max(2, a.chapter.weeks ?? 1))).slice(0, Math.min(3, candidates.length))).map((item) => item.index));
  const eras = candidates.filter((item) => retained.has(item.index));
  useEffect(() => {
    if (!selected) return;
    const close = (event: KeyboardEvent) => { if (event.key === "Escape") setSelected(null); };
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, [selected]);
  return <div><div><Eyebrow light>Your eras</Eyebrow><h2 className="mt-4 max-w-[980px] font-display text-[clamp(2.8rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-ink">This conversation had chapters.</h2><p className="mt-5 max-w-[760px] text-sm leading-relaxed text-ink/52">{eras.length} significant chapters survived the cut. Scroll through them, then open one for the full story.</p></div><div className="era-scroll mt-7" data-report-navigation-lock onClick={(event) => event.stopPropagation()} onTouchStart={(event) => event.stopPropagation()} onTouchMove={(event) => event.stopPropagation()} onTouchEnd={(event) => event.stopPropagation()}><ol className="era-timeline" style={{ "--era-count": Math.max(1, eras.length) } as CSSProperties}>{eras.map(({ chapter, index }, position) => { const note = byIndex.get(index); const title = groupEraTitle(note?.label, note?.summary, position); const color = eraColors[position % eraColors.length]; const above = position % 2 === 0; return <li key={`${chapter.startTs}-${chapter.endTs}`} className={`era-stop ${above ? "era-stop-above" : "era-stop-below"}`} style={{ "--era-position": position } as CSSProperties}><button type="button" className="era-stop-button" onClick={(event) => { event.stopPropagation(); setSelected({ chapter, index, position }); }} aria-label={`Open ${title}`}><span className="era-stop-node" style={{ background: color }}><span>{String(position + 1).padStart(2, "0")}</span></span><span className="era-stop-copy" style={{ borderColor: color }}><span className="era-stop-date">{formatDate(chapter.startTs)} — {formatDate(chapter.endTs)}</span><strong>{title}</strong><span className="era-stop-volume">{chapter.messageCount.toLocaleString()} messages · {Math.round(chapter.messagesPerMonth).toLocaleString()}/mo</span>{groupEraChangeLine(chapter) && <span className="era-stop-change">{groupEraChangeLine(chapter)}</span>}<span className="era-stop-open">open chapter ↗</span></span></button></li>; })}</ol></div>{selected && (() => { const note = byIndex.get(selected.index); const title = groupEraTitle(note?.label, note?.summary, selected.position); const color = eraColors[selected.position % eraColors.length]; const receipts = evidence?.filter((message) => note?.evidenceMessageIds.includes(message.id)); return <div className="fixed inset-0 z-[100] grid place-items-center bg-night/82 px-4 py-6 backdrop-blur-md" role="dialog" aria-modal="true" aria-labelledby="group-era-detail-title" onClick={(event) => { event.stopPropagation(); if (event.target === event.currentTarget) setSelected(null); }}><section className="rise max-h-[88dvh] w-full max-w-[820px] overflow-y-auto rounded-[28px] bg-surface p-6 text-ink shadow-2xl sm:p-9" onClick={(event) => event.stopPropagation()}><header className="flex items-start justify-between gap-6 border-b border-ink/14 pb-6"><div><p className="font-mono text-[10px] uppercase tracking-[.16em] text-accent">{formatDate(selected.chapter.startTs)} — {formatDate(selected.chapter.endTs)}</p><h3 id="group-era-detail-title" className="mt-3 font-display text-[clamp(2.4rem,6vw,5.2rem)] leading-[.9]">{title}</h3></div><button type="button" onClick={() => setSelected(null)} aria-label="Close era details" className="grid h-11 w-11 shrink-0 place-items-center rounded-full border border-ink/16 text-xl text-ink/45 transition hover:border-ink/40 hover:text-ink">×</button></header><p className="mt-6 max-w-[65ch] text-[clamp(1rem,1.8vw,1.25rem)] leading-relaxed text-ink/68">{note?.summary || "A sustained stretch with its own rhythm and conversational shape."}</p><dl className="mt-7 grid grid-cols-2 border-y border-ink/14 sm:grid-cols-4"><div className="py-4"><dd className="font-display text-3xl">{selected.chapter.messageCount.toLocaleString()}</dd><dt className="mt-1 font-mono text-[8px] uppercase tracking-[.12em] text-ink/38">messages</dt></div><div className="border-l border-ink/14 py-4 pl-5"><dd className="font-display text-3xl">{Math.round(selected.chapter.messagesPerMonth).toLocaleString()}</dd><dt className="mt-1 font-mono text-[8px] uppercase tracking-[.12em] text-ink/38">per month</dt></div><div className="py-4 sm:border-l sm:border-ink/14 sm:pl-5"><dd className="font-display text-3xl">{selected.chapter.weeks ?? "—"}</dd><dt className="mt-1 font-mono text-[8px] uppercase tracking-[.12em] text-ink/38">weeks</dt></div><div className="border-l border-ink/14 py-4 pl-5"><dd className="font-display text-3xl">{Math.round(selected.chapter.share * 100)}%</dd><dt className="mt-1 font-mono text-[8px] uppercase tracking-[.12em] text-ink/38">of the chat</dt></div></dl>{receipts?.length ? <div className="mt-7"><p className="font-mono text-[9px] uppercase tracking-[.15em] text-accent">From this era</p><div className="mt-3 grid gap-3 sm:grid-cols-2">{receipts.slice(0, 4).map((message) => <article key={message.id} className="border-t border-ink/14 pt-3"><p className="font-mono text-[8px] uppercase tracking-[.1em] text-accent">{names.get(message.participantId) ?? "Unknown"}</p><p className="mt-2 text-sm leading-relaxed text-ink/68">“{message.body}”</p></article>)}</div></div> : null}<div className="mt-8 h-1 w-20 rounded-full" style={{ background: color }} /></section></div>; })()}</div>;
}

function GroupNamedList({ eyebrow, title, items, scrollable = false }: { eyebrow: string; title: string; items: Array<{ id: string; label: string; copy: string }>; scrollable?: boolean }) {
  const list = <ol className="grid border-t border-white/14 sm:grid-cols-2">{items.map((item, index) => <li key={item.id} className={`border-b border-white/12 py-4 sm:px-5 ${index % 2 ? "sm:border-l sm:border-white/12" : "sm:pl-0"}`}><p className="font-mono text-[8px] text-accent-lit">{String(index + 1).padStart(2, "0")}</p><h3 className="mt-2 font-display text-3xl text-white">{item.label}</h3><p className="mt-2 text-xs leading-relaxed text-white/46">{item.copy}</p></li>)}</ol>;
  return <div className={scrollable ? "flex max-h-[calc(100dvh-9rem)] min-h-0 flex-col" : undefined}><div className="shrink-0"><Eyebrow>{eyebrow}</Eyebrow><h2 className="mt-4 max-w-[960px] font-display text-[clamp(2.8rem,6vw,6.4rem)] leading-[.88] text-white">{title}</h2></div>{scrollable ? <GroupScrollArea>{list}</GroupScrollArea> : <div className="mt-8">{list}</div>}</div>;
}

export function GroupReport({ analysis, ai = null, aiControl, aiEvidence, endControl, guestFinalControl, onBack, backHref, returnLabel = "Dashboard", saved = false, visibilityLabel = "Group report · local", coverActions, extremeEvidence, doubleTextEvidence, stickerVisuals, localEvidenceKey }: { analysis: GroupAnalysis; ai?: GroupAiPayload | null; aiControl?: ReactNode; aiEvidence?: LocalGroupMessage[]; endControl?: ReactNode; guestFinalControl?: ReactNode; onBack?: () => void; backHref?: string; returnLabel?: string; saved?: boolean; visibilityLabel?: string; coverActions?: ReactNode; extremeEvidence?: LocalGroupExtremeEvidence; doubleTextEvidence?: LocalGroupMessage[]; stickerVisuals?: LocalGroupStickerVisuals; localEvidenceKey?: string }) {
  const [current, setCurrent] = useState(0);
  const [direction, setDirection] = useState<1 | -1>(1);
  const touchStart = useRef<number | null>(null);
  const [storedEvidence, setStoredEvidence] = useState<LocalGroupExtremeEvidence | undefined>();
  const [storedAiEvidence, setStoredAiEvidence] = useState<LocalGroupMessage[] | undefined>();
  const [storedDoubleTextEvidence, setStoredDoubleTextEvidence] = useState<LocalGroupMessage[] | undefined>();
  const [storedStickerVisuals, setStoredStickerVisuals] = useState<LocalGroupStickerVisuals | undefined>();
  const [aiProgress, setAiProgress] = useState<AiProgressState | undefined>();
  useEffect(() => {
    const receive = (event: Event) => setAiProgress((event as CustomEvent<AiProgressState>).detail);
    window.addEventListener(TELESCOPE_AI_PROGRESS_EVENT, receive);
    return () => window.removeEventListener(TELESCOPE_AI_PROGRESS_EVENT, receive);
  }, []);
  useEffect(() => { if (aiProgress?.kind !== "done") return; const timeout = window.setTimeout(() => setAiProgress(undefined), 6000); return () => window.clearTimeout(timeout); }, [aiProgress]);
  useEffect(() => {
    if (extremeEvidence || !localEvidenceKey) return;
    try {
      const saved = localStorage.getItem(`telescope:group-extremes:${localEvidenceKey}`);
      if (saved) setStoredEvidence(JSON.parse(saved) as LocalGroupExtremeEvidence);
    } catch { /* Browser-local receipts are optional. */ }
  }, [extremeEvidence, localEvidenceKey]);
  useEffect(() => {
    if (aiEvidence || !localEvidenceKey) return;
    try {
      const saved = localStorage.getItem(`telescope:group-ai-evidence:${localEvidenceKey}`);
      if (saved) setStoredAiEvidence(JSON.parse(saved) as LocalGroupMessage[]);
    } catch { /* Browser-local AI excerpts are optional. */ }
  }, [aiEvidence, localEvidenceKey]);
  useEffect(() => {
    if (doubleTextEvidence || !localEvidenceKey) return;
    try { const saved = localStorage.getItem(`telescope:group-double-text:${localEvidenceKey}`); if (saved) setStoredDoubleTextEvidence(JSON.parse(saved) as LocalGroupMessage[]); } catch { /* Browser-local receipts are optional. */ }
  }, [doubleTextEvidence, localEvidenceKey]);
  useEffect(() => {
    if (stickerVisuals || !localEvidenceKey) return;
    try { const saved = localStorage.getItem(`telescope:group-stickers:${localEvidenceKey}`); if (saved) setStoredStickerVisuals(JSON.parse(saved) as LocalGroupStickerVisuals); } catch { /* Browser-local sticker artwork is optional. */ }
  }, [localEvidenceKey, stickerVisuals]);
  const leave = useCallback(() => {
    if (onBack) onBack();
    else if (backHref) window.location.assign(backHref);
  }, [backHref, onBack]);
  const visible = analysis.participants.slice(0, 8);
  const remainder = analysis.participants.slice(8);
  const remainderMessages = remainder.reduce((sum, person) => sum + person.messages, 0);
  const names = new Map(analysis.participants.map((person) => [person.id, person.name]));
  const visibleAiEvidence = aiEvidence ?? storedAiEvidence;
  const visibleDoubleTextEvidence = doubleTextEvidence ?? storedDoubleTextEvidence;
  const visibleStickerVisuals = stickerVisuals ?? storedStickerVisuals;
  const restart = useCallback(() => { setDirection(-1); setCurrent(0); }, []);

  const slides = useMemo<GroupSlide[]>(() => [
    { id: "opening", label: "opening", tone: "night", content: <div><div className="flex justify-end"><span className="hidden font-mono text-[9px] uppercase tracking-[.18em] text-white/30 sm:inline">{visibilityLabel}</span></div><div className={`mt-[clamp(2.5rem,9vh,6.5rem)] ${aiControl ? "grid items-end gap-8 lg:grid-cols-[minmax(0,1fr)_320px]" : ""}`}><div><Eyebrow>Your group chat report</Eyebrow><h1 className="mt-5 max-w-[1050px] font-display text-[clamp(4rem,10vw,10rem)] leading-[.78] tracking-[-.045em] text-white">{analysis.chat.name}</h1><p className="mt-7 max-w-[680px] text-lg text-white/48">{analysis.participants.length} people left {analysis.totalMessages.toLocaleString()} messages in this room. Everything here was counted locally.</p></div>{aiControl}</div></div> },
    { id: "overview", label: "at a glance", tone: "night", content: <div><Eyebrow>The whole room</Eyebrow><h2 className="mt-4 max-w-[940px] font-display text-[clamp(3rem,7vw,7rem)] leading-[.86] tracking-[-.035em] text-white">A conversation this big leaves a shape.</h2><div className="mt-10 grid gap-5 border-t border-white/14 pt-6 sm:grid-cols-3"><div><p className="font-display text-[clamp(2rem,4vw,4.5rem)] text-white">{analysis.totalMessages.toLocaleString()}</p><p className="mt-1 font-mono text-[9px] uppercase tracking-[.13em] text-white/38">messages</p></div><div><p className="font-display text-[clamp(2rem,4vw,4.5rem)] text-white">{analysis.span.activeDays.toLocaleString()}</p><p className="mt-1 font-mono text-[9px] uppercase tracking-[.13em] text-white/38">active days</p></div><div><p className="font-display text-[clamp(1.6rem,3vw,3.3rem)] text-white">{formatDate(analysis.span.firstTs)} — {formatDate(analysis.span.lastTs)}</p><p className="mt-1 font-mono text-[9px] uppercase tracking-[.13em] text-white/38">time together</p></div></div></div> },
    { id: "participation", label: "who filled the room", tone: "light", content: <div className="grid items-center gap-8 lg:grid-cols-[minmax(250px,.55fr)_minmax(0,1.45fr)] lg:gap-12"><div><Eyebrow light>Participation</Eyebrow><h2 className="mt-4 font-display text-[clamp(2.7rem,6vw,6.4rem)] leading-[.88] tracking-[-.035em] text-ink">Who filled the room.</h2><p className="mt-5 max-w-[38ch] text-sm leading-relaxed text-ink/52">Message share across every active sender in the export.</p></div><ol className="border-t border-ink/14">{visible.map((person, index) => <li key={person.id} className="grid grid-cols-[24px_minmax(80px,.7fr)_minmax(55px,1.3fr)_auto] items-center gap-2 border-b border-ink/12 py-2.5 sm:gap-4"><span className="font-mono text-[9px] text-accent-deep">{String(index + 1).padStart(2, "0")}</span><span className="truncate font-display text-lg sm:text-xl">{person.name}</span><span className="h-1.5 overflow-hidden rounded-full bg-ink/8"><span className="block h-full rounded-full bg-accent" style={{ width: `${Math.max(1, person.share * 100)}%` }} /></span><span className="text-right font-mono text-[8px] uppercase tracking-[.08em] text-ink/42">{(person.share * 100).toFixed(1)}%</span></li>)}{remainder.length > 0 && <li className="grid grid-cols-[24px_minmax(80px,.7fr)_minmax(55px,1.3fr)_auto] items-center gap-2 border-b border-ink/12 py-2.5 text-ink/45 sm:gap-4"><span className="font-mono text-[9px]">＋</span><span className="truncate font-display text-lg sm:text-xl">{remainder.length} others</span><span className="h-1.5 overflow-hidden rounded-full bg-ink/8"><span className="block h-full rounded-full bg-ink/28" style={{ width: `${Math.max(1, (remainderMessages / analysis.totalMessages) * 100)}%` }} /></span><span className="text-right font-mono text-[8px] uppercase tracking-[.08em]">{remainderMessages.toLocaleString()}</span></li>}</ol></div> },
    { id: "who-starts", label: "who starts it", tone: "light", content: <WhoStartsGroup analysis={analysis} /> },
    ...(analysis.doubleTexting?.longest ? [{ id: "double-texting", label: "double texter award", tone: "night" as const, content: <GroupDoubleTexter analysis={analysis} names={names} evidence={visibleDoubleTextEvidence} /> }] : []),
    { id: "months", label: "messages per month", tone: "light", content: <GroupMonthly analysis={analysis} /> },
    { id: "changing-room", label: "who led each month", tone: "light", content: <ChangingRoom analysis={analysis} /> },
    { id: "hours", label: "when you talk", tone: "night", content: <GroupClock analysis={analysis} /> },
    ...(ai?.eras?.length ? [{ id: "ai-eras", label: "your eras", tone: "light" as const, content: ai.eraChapters?.length ? <GroupEraSlide ai={ai} evidence={visibleAiEvidence} names={names} /> : <GroupNamedList eyebrow="Your eras" title="This conversation had chapters." items={ai.eras.map((item, index) => ({ id: item.id ?? `era-${index + 1}`, label: item.label, copy: item.summary }))} /> }] : []),
    { id: "speech", label: "how you speak", tone: "night", content: <GroupSpeech analysis={analysis} /> },
    ...(analysis.emoji?.length ? [{ id: "emoji", label: "emoji", tone: "night" as const, content: <GroupEmoji analysis={analysis} /> }] : []),
    ...(analysis.stickers?.length ? [{ id: "stickers", label: "stickers", tone: "night" as const, content: <GroupStickers analysis={analysis} visuals={visibleStickerVisuals} /> }] : []),
    { id: "language", label: "your language", tone: "night", content: <GroupLanguage analysis={analysis} /> },
    ...(ai?.lore?.length ? [{ id: "ai-lore", label: "the lore", tone: "night" as const, content: <GroupNamedList eyebrow="Recurring lore" title="The references that became communal property." items={ai.lore.map((item) => ({ id: item.id, label: item.label, copy: item.explanation }))} scrollable /> }] : []),
    ...((ai?.topics ?? ai?.themes ?? []).length ? [{ id: "ai-topics", label: "what you talk about", tone: "light" as const, content: <GroupTopics ai={ai!} /> }] : []),
    ...(ai?.wildTexts?.slice(0, 5).map((item, index, all) => ({ id: `wild-text-${index + 1}`, label: `who said it · ${index + 1}`, tone: "night" as const, content: <WildTextGame item={item} position={index + 1} total={all.length} participants={analysis.participants} names={names} /> })) ?? []),
    { id: "replies", label: "who answers whom", tone: "night", content: <div className="grid items-center gap-8 lg:grid-cols-[minmax(260px,.7fr)_minmax(0,1.3fr)] lg:gap-14"><div><Eyebrow>Reply network</Eyebrow><h2 className="mt-4 font-display text-[clamp(2.8rem,6.5vw,6.6rem)] leading-[.86] tracking-[-.035em] text-white">Who keeps answering whom.</h2></div>{analysis.replyPairs.length ? <ol className="border-t border-white/14">{analysis.replyPairs.slice(0, 8).map((pair, index) => <li key={`${pair.fromId}-${pair.toId}`} className="grid grid-cols-[24px_1fr_auto] gap-3 border-b border-white/12 py-3"><span className="font-mono text-[9px] text-accent-lit">{String(index + 1).padStart(2, "0")}</span><p className="truncate text-sm text-white/68"><span className="text-white">{names.get(pair.fromId)}</span> → {names.get(pair.toId)}</p><span className="font-mono text-[8px] uppercase tracking-[.08em] text-white/32">{pair.count.toLocaleString()} replies</span></li>)}</ol> : <p className="border-y border-white/14 py-8 text-sm text-white/42">This export does not contain enough reply links to draw a network yet.</p>}</div> },
    ...(analysis.strongestPair ? [{ id: "strongest-pair", label: "the strongest axis", tone: "night" as const, content: <StrongestPair analysis={analysis} /> }] : []),
    ...(analysis.reactionLeaders.length ? [{ id: "reactions", label: "reaction magnet", tone: "night" as const, content: <ReactionMagnet analysis={analysis} /> }] : []),
    { id: "extremes", label: "the extremes", tone: "light", content: <GroupExtremes analysis={analysis} names={names} evidence={extremeEvidence ?? storedEvidence} /> },
    ...(ai?.roles.length ? [{ id: "ai-roles", label: "group roles", tone: "night" as const, content: <GroupRoles ai={ai} names={names} evidence={visibleAiEvidence} /> }] : []),
    ...(endControl ? [{ id: "save-report", label: "save and share", tone: "night" as const, content: endControl }] : []),
    { id: "finale", label: "the final word", tone: "night", content: <div className="text-center"><Eyebrow>End of report</Eyebrow><h2 className="mx-auto mt-5 max-w-[980px] font-display text-[clamp(3rem,7vw,7rem)] leading-[.88] tracking-[-.035em] text-white">{analysis.participants.length} people. <span className="italic text-accent-lit">One very crowded conversation.</span></h2>{guestFinalControl ?? <p className="mx-auto mt-7 max-w-[620px] text-base leading-relaxed text-white/48">{saved ? "The numerical group report is saved to your account." : visibilityLabel.startsWith("Shared") ? "This shared report contains numerical results only. Private message receipts stay hidden." : "This group report exists only in this tab."}</p>}<div className="mt-7 flex flex-wrap justify-center gap-3"><button type="button" onClick={restart} className="inline-flex items-center gap-2 rounded-full border border-white/18 px-6 py-3.5 text-sm font-semibold text-white/62 transition hover:-translate-y-0.5 hover:border-white/45 hover:text-white"><span aria-hidden="true">↺</span> Replay</button><button type="button" onClick={leave} className="inline-flex items-center gap-2 px-4 py-3.5 text-sm font-semibold text-white/42 transition hover:text-white">{backHref ? returnLabel : "New analysis"} <span aria-hidden="true">→</span></button></div></div> },
  ], [ai, aiControl, analysis, backHref, endControl, extremeEvidence, guestFinalControl, leave, names, remainder.length, remainderMessages, restart, returnLabel, saved, storedEvidence, visibilityLabel, visible, visibleAiEvidence, visibleDoubleTextEvidence, visibleStickerVisuals]);

  const go = useCallback((next: number) => { const bounded = Math.max(0, Math.min(slides.length - 1, next)); if (bounded === current) return; setDirection(bounded > current ? 1 : -1); setCurrent(bounded); }, [current, slides.length]);
  const advance = useCallback(() => go(current + 1), [current, go]);
  const retreat = useCallback(() => go(current - 1), [current, go]);
  useEffect(() => { const onKey = (event: KeyboardEvent) => { if (["ArrowRight", "ArrowDown", "PageDown", " "].includes(event.key)) { event.preventDefault(); advance(); } if (["ArrowLeft", "ArrowUp", "PageUp"].includes(event.key)) { event.preventDefault(); retreat(); } if (event.key === "Home") go(0); if (event.key === "End") go(slides.length - 1); }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, [advance, go, retreat, slides.length]);
  const clickAdvance = (event: React.MouseEvent<HTMLElement>) => { if ((event.target as HTMLElement).closest("a,button,input,textarea,select,[role='button'],[role='dialog'],[data-report-navigation-lock]")) return; advance(); };

  return <main aria-label="Your group chat report" className="relative h-dvh overflow-hidden bg-night" onClick={clickAdvance} onTouchStart={(event) => { if ((event.target as HTMLElement).closest("[data-report-navigation-lock]")) { touchStart.current = null; return; } touchStart.current = event.touches[0]?.clientX ?? null; }} onTouchEnd={(event) => { if ((event.target as HTMLElement).closest("[data-report-navigation-lock]")) { touchStart.current = null; return; } if (touchStart.current === null) return; const delta = (event.changedTouches[0]?.clientX ?? touchStart.current) - touchStart.current; if (Math.abs(delta) > 45) delta < 0 ? advance() : retreat(); touchStart.current = null; }}>
    {slides.map((slide, index) => <GroupScreen key={slide.id} slide={slide} active={index === current} index={index} total={slides.length} direction={direction} />)}
    <div className="fixed left-5 top-5 z-40 sm:left-10"><button type="button" onClick={leave} aria-label={backHref ? `Back to ${returnLabel.toLocaleLowerCase()}` : "Start a new analysis"} className="report-back-button inline-flex h-11 items-center gap-2.5 rounded-full border border-white/14 bg-night/72 px-4 font-mono text-[9px] uppercase tracking-[.16em] text-white/58 backdrop-blur transition hover:border-accent-lit hover:text-white"><svg aria-hidden="true" viewBox="0 0 24 24" className="h-[18px] w-[18px] shrink-0 fill-none stroke-current" strokeWidth="1.7"><path d="M19 12H5m0 0 5-5m-5 5 5 5" strokeLinecap="round" strokeLinejoin="round" /></svg><span>{backHref ? returnLabel : "New analysis"}</span></button></div>
    {coverActions && <div className={`report-cover-actions fixed right-5 top-5 z-40 sm:right-10 ${slides[current]?.tone === "light" ? "report-actions-light" : ""}`}>{coverActions}</div>}
    {aiProgress && <AiProgressSignal state={aiProgress} />}
    <div className="fixed inset-x-0 bottom-0 z-30 h-1 bg-white/8"><span key={current} className="wrapped-progress-fill block h-full bg-accent-lit transition-[width] duration-500" style={{ width: `${((current + 1) / slides.length) * 100}%` }} /></div>
    <nav aria-label="Report navigation" className="fixed bottom-5 right-5 z-40 flex items-center gap-2 sm:right-10"><button type="button" onClick={retreat} disabled={current === 0} aria-label="Previous screen" className="grid h-11 w-11 place-items-center rounded-full border border-white/16 bg-night/70 text-white/70 backdrop-blur transition hover:border-accent-lit hover:text-white disabled:pointer-events-none disabled:opacity-20">←</button><button type="button" onClick={advance} disabled={current === slides.length - 1} aria-label="Next screen" className="grid h-11 w-11 place-items-center rounded-full border border-white/16 bg-night/70 text-white/70 backdrop-blur transition hover:border-accent-lit hover:text-white disabled:pointer-events-none disabled:opacity-20">→</button></nav>
  </main>;
}
